<html lang="<?= e(\Panel\Core\I18n::current()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?= e($_SESSION['csrf']) ?>"><title><?= e(tr('安装 · Cloudflare SaaS自动接入面板')) ?></title><link rel="stylesheet" href="/assets/app.css?v=<?= e(\Panel\Core\Version::current()) ?>"><script src="/assets/i18n.js?v=<?= e(\Panel\Core\Version::current()) ?>" defer></script><script src="/assets/app.js?v=<?= e(\Panel\Core\Version::current()) ?>" defer></script></head>
<body class="setup-page"><div class="setup-locale"><?php require __DIR__.'/locale.php'; ?></div><main class="setup-shell"><div class="eyebrow">CLOUDFLARE SAAS PANEL</div><h1><?= e(tr('安装自动接入面板')) ?></h1><p class="muted"><?= e(tr('完成环境检查与管理员配置，开始管理域名接入。')) ?></p>
<section class="card"><h2><?= e(tr('运行环境')) ?></h2><div class="checks"><?php foreach ($checks as $name=>$ok): ?><span class="check <?= $ok?'ok':'bad' ?>"><?= $ok?'✓':'×' ?> <?= e(tr($name)) ?></span><?php endforeach ?></div></section>
