<div class="form-grid"><label><?= e(tr('数据库地址')) ?><input name="db_host" required value="<?= e($defaults['db_host']) ?>"></label><label><?= e(tr('端口')) ?><input name="db_port" type="number" required value="<?= e($defaults['db_port']) ?>"></label><label><?= e(tr('数据库名称')) ?><input name="db_name" required value="<?= e($defaults['db_name']) ?>"></label><label><?= e(tr('数据库用户')) ?><input name="db_user" required value="<?= e($defaults['db_user']) ?>"></label></div><label><?= e(tr('数据库密码')) ?><input name="db_password" type="password" autocomplete="new-password" placeholder="<?= e(tr('Docker 使用 .env 中的 MYSQL_PASSWORD')) ?>"></label><hr><div class="form-grid"><label><?= e(tr('管理员用户名')) ?><input name="username" required autocomplete="username"></label><label><?= e(tr('管理员密码')) ?><input name="password" type="password" minlength="12" maxlength="72" required autocomplete="new-password" placeholder="<?= e(tr('12 至 72 字节')) ?>"></label></div><p class="hint"><?= e(tr('安装会初始化数据库并锁定安装入口，请使用本项目专用的空数据库。')) ?></p><button class="primary" type="submit"><?= e(tr('完成安装')) ?></button></form><div class="toast" id="toast" role="status" hidden></div></main></body></html>
